def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opps = []
    prev_bids = []
    urgent_opp_count = 0
    rich_opp_pressure = 0.0

    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opps.append(opp)
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                urgent_opp_count += 1
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
                if opp.get('budget', 0) > budget * 0.8:
                    rich_opp_pressure = max(rich_opp_pressure, float(bid))

    if not alive_opps:
        return float(min(budget, 18.0 if hp > 3 else 40.0))

    slots = max(1, int(supply // WATER_REQ))
    competitors = 1 + len(alive_opps)
    scarcity = competitors - slots

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    need_score = 0
    if hp <= 2:
        need_score += 4
    elif hp <= 4:
        need_score += 2
    if no_water >= 2:
        need_score += 4
    elif no_water >= 1:
        need_score += 2

    pressure = 0
    if scarcity >= 3:
        pressure += 3
    elif scarcity >= 1:
        pressure += 2
    if supply <= 16:
        pressure += 2
    elif supply <= 19:
        pressure += 1
    pressure += min(2, urgent_opp_count)

    if need_score >= 6:
        base = max(62.0, highest_prev + 2.5, avg_prev + 6.0)
    elif need_score >= 3:
        base = max(42.0, avg_prev * 0.72 + 4.0, highest_prev * 0.52 + 3.0)
    else:
        if pressure >= 4:
            base = max(28.0, avg_prev * 0.45, rich_opp_pressure * 0.38)
        elif pressure >= 2:
            base = max(18.0, avg_prev * 0.28)
        else:
            base = 10.0 + max(0.0, (18.0 - supply) * 1.2)

    if highest_prev >= 120 and need_score <= 2:
        base = min(base, 24.0)
    if highest_prev >= 145 and need_score <= 4:
        base = min(base, 32.0)

    reserve = 0.0
    if hp <= 3 or no_water >= 1:
        reserve = 0.0
    else:
        reserve = DAILY_SALARY * 0.35

    max_affordable = max(0.0, budget - reserve)
    bid = min(base, max_affordable)

    if need_score >= 6:
        bid = min(max_affordable, max(bid, DAILY_SALARY * 0.9))
    elif need_score >= 3 and pressure >= 3:
        bid = min(max_affordable, max(bid, DAILY_SALARY * 0.68))

    if bid < 0:
        bid = 0.0
    return float(min(budget, round(bid, 2)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = int(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive.append((oid, o))

    if not alive:
        cap = DAILY_SALARY * 0.4
        return float(min(budget, cap))

    # Extract yesterday bids from previous_trace for immediate reaction
    prev_bids = []
    prev_by_id = {}
    for oid, o in alive:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                b = float(b)
                prev_bids.append(b)
                prev_by_id[oid] = b
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    avg_prev_bid = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    # Tight supply => more competition for water; use opponents' pressure to decide
    supply_ratio = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY + 1e-9)  # 0..1
    tightness = 1.0 - max(0.0, min(1.0, supply_ratio))

    # If our hp is low, prioritize survival; if our hp is high, shade to save budget
    low_hp = hp <= 2
    critical = hp <= 3 or no_water_days >= 1

    # Determine target bid based on yesterday's max pressure
    # If someone previously bid very high (Cindy-like), we don't need to match unless tight+critical.
    pressure_threshold = DAILY_SALARY * 1.5  # 135

    # Base aggressiveness from tightness and hp
    if critical:
        base = DAILY_SALARY * (0.65 + 0.25 * tightness)
    elif low_hp:
        base = DAILY_SALARY * 0.95
    else:
        base = DAILY_SALARY * (0.45 + 0.25 * tightness)

    # React to observed pressure
    if highest_prev_bid >= pressure_threshold:
        # Overpayers exist; shade unless we are critical and supply is tight.
        if critical and tightness >= 0.6:
            target = max(base, highest_prev_bid * 0.72)
        else:
            target = min(base, avg_prev_bid * 0.75 if avg_prev_bid > 0 else base)
    else:
        # No extreme overbids: bid around base, slightly above average pressure if needed.
        if tightness >= 0.7 and highest_prev_bid > 0:
            target = max(base, highest_prev_bid * 0.6)
        else:
            target = base

    # Convert to a practical cap: cannot exceed budget.
    # Also avoid wasting too much when not critical.
    if critical:
        budget_cap = DAILY_SALARY * 1.2
    else:
        budget_cap = DAILY_SALARY * 0.9

    bid = float(min(budget, budget_cap, target))

    # Ensure non-negative and at least a minimal bid if we can afford it.
    if bid < 0.0:
        bid = 0.0

    # If we are extremely likely to lose (hp low), bump to ensure water.
    # Use supply to estimate how many water units might be needed: more tightness => higher chance.
    if critical and supply <= (MIN_SUPPLY + WATER_REQ):
        # bump modestly
        bid = float(min(budget, max(bid, DAILY_SALARY * (0.75 + 0.1 * tightness))))

    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    max_prev = max(yesterday_bids) if yesterday_bids else 80

    if my_status['hp'] <= 3:
        return min(my_status['budget'], max_prev * 1.1)

    if supply < 18:
        return min(my_status['budget'], max(85, max_prev * 1.05))

    if supply > 22:
        return min(my_status['budget'], 60)

    return min(my_status['budget'], max(75, max_prev * 0.95))
